internal static class WidgetTheme { internal static readonly Brush Primary=new SolidColorBrush(Color.FromRgb(250,246,240)),Secondary=new SolidColorBrush(Color.FromRgb(211,202,211)),Tertiary=new SolidColorBrush(Color.FromRgb(173,162,177)),Hairline=new SolidColorBrush(Color.FromArgb(42,255,255,255));internal static readonly CornerRadius CardRadius=new(24);internal static readonly Thickness CardPadding=new(14);internal static LinearGradientBrush PlumSurface()=>Gradient(Color.FromRgb(65,31,51),Color.FromRgb(28,26,42));internal static LinearGradientBrush Gradient(Color a,Color b)=>new(new GradientStopCollection{new(a,0),new(b,1)},135);internal static Border Card(UIElement x)=>Card(new CanvasItem(),x);internal static Border Card(CanvasItem i,UIElement x)=>new(){Child=x,Background=Surface(i),BorderBrush=Hairline,BorderThickness=new Thickness(1),CornerRadius=CardRadius,Padding=CardPadding,ClipToBounds=true,Effect=new DropShadowEffect{Color=Colors.Black,ShadowDepth=4,BlurRadius=20,Opacity=.3}};private static Brush Surface(CanvasItem i)=>(i.Theme switch{WidgetThemeKind.Light=>Gradient(Color.FromRgb(250,250,250),Color.FromRgb(225,230,235)),WidgetThemeKind.Dark=>Gradient(Color.FromRgb(42,45,55),Color.FromRgb(16,18,25)),WidgetThemeKind.Rose=>Gradient(Color.FromRgb(126,54,82),Color.FromRgb(48,25,43)),WidgetThemeKind.Ocean=>Gradient(Color.FromRgb(38,102,139),Color.FromRgb(18,39,73)),WidgetThemeKind.Mint=>Gradient(Color.FromRgb(48,120,100),Color.FromRgb(19,58,52)),_=>PlumSurface()});internal static ControlTemplate RoundButtonTemplate(){var b=new FrameworkElementFactory(typeof(Border));b.SetValue(Border.CornerRadiusProperty,new CornerRadius(99));b.SetBinding(Border.BackgroundProperty,new System.Windows.Data.Binding("Background"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});var p=new FrameworkElementFactory(typeof(ContentPresenter));p.SetBinding(ContentPresenter.ContentProperty,new System.Windows.Data.Binding("Content"){RelativeSource=new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)});b.AppendChild(p);return new ControlTemplate(typeof(Button)){VisualTree=b};}}
internal sealed class NowPlayingItemContent:IDesktopItemContent{private readonly CanvasItem item;private readonly INowPlayingService s;private readonly Border root,artFrame;private readonly Image art=new(){Stretch=Stretch.UniformToFill};private readonly TextBlock title=new(){FontSize=18,FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis},artist=new(){FontSize=12},time=new(){FontSize=10};private readonly Slider seek=new(){Opacity=.01};private readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(250)};private readonly StackPanel visual=new(){Orientation=Orientation.Horizontal};private IDisposable? lease;private NowPlayingSnapshot snap=NowPlayingSnapshot.Empty;private bool active;internal NowPlayingItemContent(CanvasItem i,INowPlayingService service){item=i;s=service;artFrame=new Border{Width=94,Height=94,CornerRadius=new CornerRadius(17),ClipToBounds=true,Child=art,Margin=new Thickness(0,0,14,0)};artFrame.MouseLeftButtonUp+=Activate;title.MouseLeftButtonUp+=Activate;var info=new StackPanel{VerticalAlignment=VerticalAlignment.Center};info.Children.Add(title);info.Children.Add(artist);var h=new Grid();h.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});h.ColumnDefinitions.Add(new ColumnDefinition());h.Children.Add(artFrame);Grid.SetColumn(info,1);h.Children.Add(info);var track=new Grid{Height=16};track.Children.Add(new Border{Height=4,Background=WidgetTheme.Hairline,CornerRadius=new CornerRadius(2),VerticalAlignment=VerticalAlignment.Center});track.Children.Add(seek);seek.PreviewMouseLeftButtonUp+=async(_,_)=>{if(snap.CanSeek)await s.SeekAsync(TimeSpan.FromSeconds(seek.Value));};var controls=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};controls.Children.Add(B("M10 3V13M13 4V12L4 8Z",40,()=>s.PreviousAsync()));controls.Children.Add(B("M5 3L14 8L5 13Z",46,()=>s.PlayPauseAsync()));controls.Children.Add(B("M6 4V12L15 8ZM3 3V13",40,()=>s.NextAsync()));for(var n=0;n<7;n++)visual.Children.Add(new Border{Width=3,Height=5+n%4*5,Margin=new Thickness(1),Background=new SolidColorBrush(Color.FromRgb(251,208,190)),VerticalAlignment=VerticalAlignment.Center});controls.Children.Add(visual);var p=new StackPanel();p.Children.Add(h);p.Children.Add(track);p.Children.Add(time);p.Children.Add(controls);root=WidgetTheme.Card(i,p);timer.Tick+=(_,_)=>Update(s.Snapshot);Update(s.Snapshot);}public UIElement View=>root;public bool HasInteractiveControls=>true;public bool IsInteractiveHit(Point p){var d=root.InputHitTest(p)as DependencyObject;while(d is not null){if(d is Button or Slider||ReferenceEquals(d,artFrame)||ReferenceEquals(d,title))return true;d=VisualTreeHelper.GetParent(d);}return false;}public void SetActive(bool v){if(active==v)return;active=v;if(v){s.SnapshotChanged+=Changed;lease=s.Acquire();timer.Start();}else{s.SnapshotChanged-=Changed;lease?.Dispose();lease=null;timer.Stop();}}private void Changed(object? _,NowPlayingSnapshot x)=>root.Dispatcher.BeginInvoke(()=>Update(x));private void Update(NowPlayingSnapshot x){snap=x;title.Text=x.Title;artist.Text=x.Artist;artFrame.Visibility=item.NowPlaying.ShowAlbumArt?Visibility.Visible:Visibility.Collapsed;seek.Maximum=Math.Max(1,x.End.TotalSeconds);seek.Value=Math.Clamp(x.Position.TotalSeconds,0,seek.Maximum);seek.IsEnabled=x.CanSeek;time.Text=x.End>TimeSpan.Zero?$"{x.Position:m\\:ss}   −{(x.End-x.Position):m\\:ss}":"";for(var n=0;n<visual.Children.Count;n++)visual.Children[n].Height=x.State==NowPlayingState.Playing?7+(DateTime.UtcNow.Millisecond/100+n*3)%16:5;}private void Activate(object? _,System.Windows.Input.MouseButtonEventArgs e){new ActivationService().TryActivate(snap.SourceApp);e.Handled=true;}internal void Refresh()=>Update(s.Snapshot);public void Dispose()=>SetActive(false);private static Button B(string d,double z,Func<Task<bool>> go){var b=new Button{Width=z,Height=z,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Template=WidgetTheme.RoundButtonTemplate(),Content=new Viewbox{Child=new Path{Data=Geometry.Parse(d),Fill=Brushes.White}}};b.Click+=async(_,_)=>await go();return b;}}
internal sealed class SystemMonitorItemContent:IDesktopItemContent{private readonly CanvasItem item;private readonly ISystemMetricsService s;private readonly Border root;private readonly TextBlock cpu=new(),ram=new(),gpu=new(),net=new(),clock=new(){FontSize=10};private IDisposable? lease;private bool active;internal SystemMonitorItemContent(CanvasItem i,ISystemMetricsService service){item=i;s=service;var p=new StackPanel();p.Children.Add(new TextBlock{Text="◈  SYSTEM STATUS",FontSize=10,FontWeight=FontWeights.SemiBold});p.Children.Add(clock);var rings=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};foreach(var x in new[]{cpu,ram,gpu}){x.Width=62;x.Height=62;x.TextAlignment=TextAlignment.Center;x.VerticalContentAlignment=VerticalAlignment.Center;x.Padding=new Thickness(0,22,0,0);x.Background=new SolidColorBrush(Color.FromArgb(38,255,255,255));rings.Children.Add(x);}p.Children.Add(rings);p.Children.Add(net);root=WidgetTheme.Card(i,p);Update(s.Snapshot);}public UIElement View=>root;public void SetActive(bool v){if(active==v)return;active=v;if(v){s.SnapshotChanged+=Changed;lease=s.Acquire();}else{s.SnapshotChanged-=Changed;lease?.Dispose();lease=null;}}private void Changed(object? _,SystemMetricsSnapshot x)=>root.Dispatcher.BeginInvoke(()=>Update(x));private void Update(SystemMetricsSnapshot x){cpu.Text=x.Cpu.Availability==MetricAvailability.Loading?"…":x.Cpu.Text;ram.Text=x.Memory.Availability==MetricAvailability.Loading?"…":x.Memory.Text;gpu.Text=x.Gpu.Availability==MetricAvailability.Loading?"…":x.Gpu.Text;clock.Text="CPU  "+ProcessorClock.Read();net.Margin=new Thickness(0,14,0,0);net.Text="↓ Download  "+x.Download.Text+"     ↑ Upload  "+x.Upload.Text;cpu.Visibility=item.SystemMonitor.ShowCpu?Visibility.Visible:Visibility.Collapsed;ram.Visibility=item.SystemMonitor.ShowMemory?Visibility.Visible:Visibility.Collapsed;gpu.Visibility=item.SystemMonitor.ShowGpu?Visibility.Visible:Visibility.Collapsed;}internal void Refresh()=>Update(s.Snapshot);public void Dispose()=>SetActive(false);}
internal static class ProcessorClock{[StructLayout(LayoutKind.Sequential)]private struct P{public uint A,B,C,D,E,F;}[DllImport("powrprof.dll")]private static extern uint CallNtPowerInformation(int l,IntPtr i,int n,[Out]P[] o,int z);internal static string Read(){try{var p=new P[Math.Max(1,Environment.ProcessorCount)];return CallNtPowerInformation(11,IntPtr.Zero,0,p,Marshal.SizeOf<P>()*p.Length)==0?SystemMetricMath.FormatProcessorClock(p.Select(x=>x.C)):"-- GHz";}catch(Exception){return "-- GHz";}}}
